def profile_bytes(profile):
    if type(profile) is not str or profile not in PROFILES:raise ValueError('Unsupported desktop HDR profile')
    return (json.dumps(dict(kind='BoilerDesktopHdrProfileV1',schema_version=1,profile=profile,**PROFILES[profile]),sort_keys=True,separators=(',',':'))+'\n').encode()

def validate_contract(resource):
    if (not isinstance(REVIEWED_BUNDLE_SHA256,str) or not re.fullmatch('[0-9a-f]{64}',REVIEWED_BUNDLE_SHA256)
            or not isinstance(REVIEWED_PAYLOAD,list) or not REVIEWED_PAYLOAD
            or not isinstance(REVIEWED_INSTALL_FILES,list) or not REVIEWED_INSTALL_FILES
            or not isinstance(REVIEWED_METADATA,dict) or set(REVIEWED_METADATA)!={'hardware_requires','compatibility','external_component_dependencies'}):
        raise ValueError('Desktop HDR reviewed R2 native inventory is not frozen')
    if (resource.get('id')!=IDENTITY or type(resource.get('install')) is not dict or set(resource['install'])!={'kind','files'} or resource['install'].get('kind')!=KIND
            or type(resource.get('payload')) is not dict or set(resource['payload'])!={'files'}
            or resource.get('verify')!={'kind':'sha256-v1'} or resource.get('restore')!={'kind':'transaction-backup-v1'}
            or resource.get('hooks') or resource.get('dynamic_handler') or resource.get('dependencies')!=[]
            or resource.get('profiles')!=PROFILES or resource.get('desktop_bundle_sha256')!=REVIEWED_BUNDLE_SHA256
            or resource.get('payload',{}).get('files')!=REVIEWED_PAYLOAD or resource['install'].get('files')!=REVIEWED_INSTALL_FILES
            or any(resource.get(k)!=v for k,v in REVIEWED_METADATA.items())):
        raise ValueError('Desktop HDR resource differs from reviewed fixed contract')
    for key in PROFILES:
        name='payload/desktop/profile-'+key+'.json';raw=profile_bytes(key)
        matches=[row for row in REVIEWED_PAYLOAD if row.get('path')==name]
        if len(matches)!=1 or matches[0].get('size')!=len(raw) or matches[0].get('sha256')!=hashlib.sha256(raw).hexdigest():
            raise ValueError('Desktop HDR profile template differs')
    return resource

def render(resource,parameters):
    validate_contract(resource)
    if type(parameters) is not dict or set(parameters)!={'profile'} or type(parameters['profile']) is not str or parameters['profile'] not in PROFILES:
        raise ValueError('Desktop HDR requires one explicit fixed profile')
    result=copy.deepcopy(resource);result['install']['kind']='files-v1'
    profile=parameters['profile'];result['hdr_selected_profile']=profile
    result['install']['files'].append(dict(source='payload/desktop/profile-'+profile+'.json',
        target=PREFIX+'share/boiler-desktop-hdr/profile.json',scope='root-slots',mode=420))
    return result
